(window._lmI18nQueue = window._lmI18nQueue || []).push(["pt", "site-help-glossary", {
"site.help.glossary.playNow": "Jogar agora",
"site.help.glossary.helpCenter": "Central de ajuda",
"site.help.glossary.strategyGuide": "Guia de estratégia",
"site.help.glossary.unblocked": "🔓 Desbloqueado",
"site.help.glossary.glossary": "Glossário",
"site.help.glossary.ioGamesGlossary": "Glossário de jogos IO",
"site.help.glossary.termsEveryIoGame": "Mais de 40 termos que todo jogador de jogos IO deveria conhecer. Dos controles básicos às técnicas avançadas: o dicionário completo de Agar.io, Slither.io, Expanding Land e todos os jogos de células.",
"site.help.glossary.jumpToCategory": "Ir para a categoria",
"site.help.glossary.basics": "🎮 Básico",
"site.help.glossary.controls": "⌨️ Controles",
"site.help.glossary.mechanics": "⚙️ Mecânicas",
"site.help.glossary.techniques": "🎯 Técnicas",
"site.help.glossary.strategy": "🧠 Estratégia",
"site.help.glossary.community": "👥 Comunidade",
"site.help.glossary.expandingLand": "🌍 Expanding Land",
"site.help.glossary.searchTermsEG": "🔍 Buscar termos... (ex.: 'split', 'vírus', 'W')",
"site.help.glossary.noTermsFoundTry": "Nenhum termo encontrado. Tente outra busca.",
"site.help.glossary.cell": "<span class=\"emoji\">⚪</span> Célula",
"site.help.glossary.theCircularBlobYou": "A bola redonda que você controla no jogo. Sua célula cresce comendo pontinhos de comida e outras células menores. No Agar.io e no Expanding Land, você começa como uma célula minúscula e tenta virar a maior do servidor.",
"site.help.glossary.alsoCalledBlobPlayer": "Também chamada de: blob, jogador, bola",
"site.help.glossary.mass": "<span class=\"emoji\">⚖️</span> Massa",
"site.help.glossary.theSizeWeightOf": "O tamanho/peso da sua célula, mostrado como um número. Mais massa = célula maior. Você ganha massa comendo comida, outros jogadores ou vírus (se for grande o bastante). E perde massa com o decaimento natural ao longo do tempo: cerca de 0,8% a cada 4 segundos nas regras padrão do Agar.io.",
"site.help.glossary.alsoCalledSizeScore": "Também chamada de: tamanho, pontuação, peso",
"site.help.glossary.foodPellets": "<span class=\"emoji\">🟢</span> Comida / bolinhas",
"site.help.glossary.smallColoredDotsScattered": "Pontinhos coloridos espalhados pelo mapa. Comer eles dá um pouco de massa (normalmente 1 por bolinha). Eles reaparecem o tempo todo, então sempre tem algo para comer: muito útil no começo da partida, quando você ainda é pequeno demais para comer outros jogadores.",
"site.help.glossary.leaderboard": "<span class=\"emoji\">🏆</span> Ranking",
"site.help.glossary.theRankedListOf": "A lista dos melhores jogadores por massa, no canto superior direito. Entrar no ranking faz de você um alvo: todo jogador ambicioso vai vir te caçar. No Expanding Land, o ranking é atualizado em tempo real para todos os 3840 jogadores.",
"site.help.glossary.spawn": "<span class=\"emoji\">🔄</span> Spawn",
"site.help.glossary.theActOfEntering": "Entrar no jogo com uma célula nova. Ao dar spawn, você começa com pouca massa em um ponto aleatório do mapa. Depois de morrer, dá para respawnar na hora com uma célula nova.",
"site.help.glossary.controlsKeys": "⌨️ Controles e teclas",
"site.help.glossary.splitSpace": "<span class=\"emoji\">✂️</span> Split (Space)",
"site.help.glossary.pressSpaceToSplit": "Pressione <strong>Space</strong> para dar split e dividir sua célula em duas metades. Uma metade dispara para a frente em alta velocidade: use isso para pegar jogadores menores que acham que estão fora do seu alcance. Você pode dar split até 16 vezes (16 pedaços de célula). As células divididas se juntam de novo depois de um tempo de espera.",
"site.help.glossary.the2RuleYou": "💡 A regra do 2×: você só pode comer uma célula se tiver pelo menos 2× a massa dela. Quando você dá split, cada metade mantém o impulso: use isso para surpreender alvos distantes.",
"site.help.glossary.wEjectMass": "<span class=\"emoji\">🟡</span> W (ejetar massa)",
"site.help.glossary.pressWToEject": "Pressione <strong>W</strong> para ejetar uma bolinha de massa na direção do cursor. Usos: dar feed nos companheiros, atirar vírus (7 toques no W = um tiro de vírus), armar iscas em armadilhas ou diminuir de tamanho para andar mais rápido. Cada toque no W custa cerca de 15-16 de massa, mas a bolinha ejetada é um pouco menor por causa da perda de massa.",
"site.help.glossary.alsoCalledFeedEject": "Também chamado de: feed, eject, atirar massa",
"site.help.glossary.spectate": "<span class=\"emoji\">👁️</span> Modo espectador",
"site.help.glossary.watchTheGameWithout": "Assista ao jogo sem jogar. No Expanding Land há mais de 200 vagas de espectador com câmera livre: você pode voar pelo mapa inteiro e assistir qualquer jogador. Ótimo para aprender técnicas com jogadores experientes.",
"site.help.glossary.gameMechanics": "⚙️ Mecânicas do jogo",
"site.help.glossary.virus": "<span class=\"emoji\">🟢</span> Vírus",
"site.help.glossary.theSpikyGreenCircles": "Os círculos verdes com espinhos no mapa. Se você for maior que um vírus e encostar nele, você <strong>estoura</strong>: sua célula se divide em vários pedaços pequenos. Se for menor, pode se esconder atrás ou dentro de um vírus para se proteger. Você também pode atirar vírus nos inimigos: aperte W 7 vezes em um vírus para lançar um novo naquela direção.",
"site.help.glossary.virusesAreBothDefensive": "💡 Os vírus são ao mesmo tempo escudos de defesa e armas de ataque. Jogadores habilidosos usam tiros de vírus para estourar inimigos grandes e roubar a massa deles.",
"site.help.glossary.mergeRecombine": "<span class=\"emoji\">🔗</span> Merge / juntar",
"site.help.glossary.afterSplittingYourCell": "Depois do split, os pedaços da sua célula acabam se juntando de novo em uma só. O tempo para juntar depende da sua massa total: células maiores demoram mais. Durante a espera, suas células ficam sobrepostas, mas não se juntam. Quando o tempo acaba, elas grudam de uma vez.",
"site.help.glossary.decay": "<span class=\"emoji\">📉</span> Decaimento",
"site.help.glossary.allCellsLoseMass": "Todas as células perdem massa com o tempo. Isso se chama decaimento (decay) e impede que qualquer jogador cresça sem limite. A taxa de decaimento no Agar.io padrão e no Expanding Land é de cerca de <strong>0,8% da sua massa a cada 4 segundos</strong>. Células maiores perdem mais em números absolutos: uma célula de 10.000 de massa perde ~80 por ciclo, enquanto uma de 100 perde menos de 1.",
"site.help.glossary.ghostCells": "<span class=\"emoji\">👻</span> Células fantasma",
"site.help.glossary.inExpandingLandWhen": "No Expanding Land, quando você morre, suas células aparecem por um instante como \"células fantasma\" transparentes que mostram exatamente onde você foi comido. Isso ajuda a entender o que aconteceu e aprender com a sua morte: foi um split kill? Um estouro no vírus? Feed de um companheiro?",
"site.help.glossary.mapArena": "<span class=\"emoji\">🗺️</span> Mapa / arena",
"site.help.glossary.thePlayingFieldWhere": "O campo de jogo onde ficam todas as células. No Agar.io, o mapa tem tamanho fixo. No Expanding Land, o mapa <strong>muda de tamanho dinamicamente</strong> de ¼× a 4× conforme o número de jogadores ativos: mais jogadores significa uma arena maior, menos jogadores significa um mapa mais apertado, que mantém a ação intensa.",
"site.help.glossary.advancedTechniques": "🎯 Técnicas avançadas",
"site.help.glossary.tricksplit": "<span class=\"emoji\">🎯</span> Tricksplit",
"site.help.glossary.anAdvancedMoveWhere": "Um movimento avançado em que você dá split várias vezes bem rápido (double ou triple split) para alcançar um alvo que parece longe demais. Ao dar split com células já divididas, cada pedaço dispara para a frente com impulso, e o seu alcance real vai muito além de um split só. Exige timing preciso e boa posição do cursor.",
"site.help.glossary.doubleSplitSpaceSpace": "💡 Double split: Space → Space rápido. O segundo split sai do pedaço que já está em movimento e cobre 2× a distância.",
"site.help.glossary.popsplit": "<span class=\"emoji\">💥</span> Popsplit",
"site.help.glossary.aTechniqueWhereYou": "Uma técnica em que você come um vírus de propósito para se dividir em vários pedaços e logo depois dá split de novo para comer um inimigo próximo. A ideia é que as muitas células pequenas do estouro mais o impulso do split deixam você engolir um inimigo que achava que estava seguro. Alto risco, alta recompensa: você precisa de massa suficiente para sobreviver ao estouro.",
"site.help.glossary.baitAndSwitch": "<span class=\"emoji\">🪤</span> Isca",
"site.help.glossary.aStrategyWhereYou": "Uma estratégia em que você usa um pedaço pequeno da sua célula dividida como isca. O inimigo persegue o pedaço pequeno sem perceber que o seu pedaço maior está posicionado para comê-lo com um split assim que ele avançar. Funciona melhor quando você tem 2 células de tamanhos diferentes.",
"site.help.glossary.cannonSelfFeed": "<span class=\"emoji\">🔫</span> Canhão / self-feed",
"site.help.glossary.rapidlyPressingWTo": "Apertar W rapidamente para passar massa de uma das suas células para outra. Quando você tem duas células divididas, pode dar W da menor para a maior, para ela ficar grande o bastante para comer um alvo próximo. Também é chamado de \"self-feed\", porque você dá feed em si mesmo entre as suas próprias células.",
"site.help.glossary.virusShot": "<span class=\"emoji\">🚀</span> Tiro de vírus",
"site.help.glossary.pressingWIntoA": "Apertar W 7 vezes em um vírus lança um vírus novo naquela direção. Use no ataque para estourar inimigos grandes ou na defesa para criar cobertura. Cada W em um vírus custa massa, então 7 toques = cerca de 100-110 de massa no total. O vírus lançado vai em linha reta até parar.",
"site.help.glossary.lineSplit": "<span class=\"emoji\">➡️</span> Line split",
"site.help.glossary.splittingInAStraight": "Dar split em linha reta na direção do alvo para que a célula dividida percorra a maior distância possível. Colocando o cursor longe, alinhado com a sua célula e o alvo, o pedaço sai com velocidade máxima. Essencial para kills de longa distância.",
"site.help.glossary.strategyConcepts": "🧠 Estratégia e conceitos",
"site.help.glossary.teaming": "<span class=\"emoji\">🤝</span> Teaming",
"site.help.glossary.twoOrMorePlayers": "Dois ou mais jogadores cooperando para dominar o servidor. Os companheiros dão feed uns nos outros (W), coordenam ataques com vírus e se protegem. O teaming é polêmico: alguns acham injusto nos modos free-for-all. O Expanding Land tem um <strong>sistema anti-teaming</strong> que aplica penalidades de decaimento de massa a quem faz teaming demais.",
"site.help.glossary.antiTeaming": "<span class=\"emoji\">⚖️</span> Anti-teaming",
"site.help.glossary.aSystemThatPenalizes": "Um sistema que penaliza jogadores por teaming excessivo. No Expanding Land, o anti-teaming usa um <strong>sistema de decaimento com multiplicador exponencial</strong> (portado do Delta Server): cada ação (estouro no vírus, split, toque no W) aumenta um único valor de multiplicador. Seu decaimento efetivo é calculado como base_decay × pow(1.086, multiplier). O multiplicador cai sozinho com o tempo por meio de uma constante de compensação, então jogando normalmente você se recupera automaticamente, sem nenhum timer.",
"site.help.glossary.multiboxing": "<span class=\"emoji\">📱</span> Multiboxing",
"site.help.glossary.playingWithMultipleBrowser": "Jogar com várias abas do navegador ou várias contas ao mesmo tempo, controlando várias células de uma vez. No Expanding Land, o multiboxing é <strong>permitido, mas regulado</strong>: cada jogador pode usar até <strong>4 contas</strong>. Assim, jogadores habilidosos podem fazer multibox de forma estratégica e o jogo continua justo.",
"site.help.glossary.bots": "<span class=\"emoji\">🤖</span> Bots",
"site.help.glossary.automatedPlayersControlledBy": "Jogadores automáticos controlados por software, e não por pessoas. No Expanding Land, os bots do servidor e os jogadores humanos são grupos separados. Veja o <a href=\"/no-bots.html\">guia de bots</a>.",
"site.help.glossary.cornerTrap": "<span class=\"emoji\">🧱</span> Armadilha de canto",
"site.help.glossary.trappingAPlayerIn": "Encurralar um jogador no canto do mapa, de onde ele não consegue fugir. A borda do mapa bloqueia o movimento, então se você for grande o bastante e ficar entre o inimigo e o canto, ele não tem para onde ir. Um dos jeitos mais garantidos de conseguir kills para jogadores experientes.",
"site.help.glossary.soloFfa": "<span class=\"emoji\">🎮</span> Solo / FFA",
"site.help.glossary.ffaStandsForFree": "<strong>FFA</strong> significa Free-For-All (todos contra todos). Cada jogador joga sozinho, sem times definidos.",
"site.help.glossary.slowPlay": "<span class=\"emoji\">🐢</span> Jogo lento",
"site.help.glossary.aPatientStrategyWhere": "Uma estratégia paciente em que você evita dar split, a não ser que o kill seja garantido. Em vez de perseguir todo alvo, você cresce comendo comida e espera os inimigos errarem. Quem joga devagar costuma sobreviver mais tempo e acumular massa de forma constante. Especialmente eficaz em arenas com muitos jogadores, como o Expanding Land.",
"site.help.glossary.communityMods": "👥 Comunidade e mods",
"site.help.glossary.modExtension": "<span class=\"emoji\">🧩</span> Mod / extensão",
"site.help.glossary.aBrowserExtensionThat": "Uma extensão de navegador que melhora o jogo com recursos extras: skins personalizadas, minimapa, controle de zoom, macros e mais. Entre os mods populares para Agar.io e Expanding Land estão <a href=\"https://www.legendmod.ml/\" style=\"color:#6ee7b7\">Legend Mod</a>, <a href=\"https://deltio.pages.dev/\" style=\"color:#6ee7b7\">Delta</a> e <a href=\"https://agar2.com/\" style=\"color:#6ee7b7\">Agar2</a>.",
"site.help.glossary.skin": "<span class=\"emoji\">🎨</span> Skin",
"site.help.glossary.aCustomImageDisplayed": "Uma imagem personalizada mostrada na sua célula no lugar da cor padrão. As skins podem ser bandeiras de países, memes, logos ou artes próprias. No Agar.io, a maioria das skins é paga. No Expanding Land, as skins são <strong>grátis</strong> com mods como o Legend Mod.",
"site.help.glossary.clan": "<span class=\"emoji\">🏰</span> Clã",
"site.help.glossary.aGroupOfPlayers": "Um grupo de jogadores que jogam juntos, geralmente identificados por uma tag em comum no nome (ex.: [LC] para <a href=\"https://join.lc\" style=\"color:#6ee7b7\">Legend Clan</a>). Os clãs costumam ter seus próprios servidores no Discord, sessões de treino e rankings internos.",
"site.help.glossary.privateServer": "<span class=\"emoji\">🖥️</span> Servidor privado",
"site.help.glossary.aGameServerRun": "Um servidor de jogo que funciona de forma independente dos servidores oficiais do Agar.io. Servidores privados podem ter regras próprias, limites de jogadores maiores e recursos diferentes. O <a href=\"https://expanding.land/\" style=\"color:#6ee7b7\">Expanding Land</a> é um servidor privado criado do zero em C, com suporte para até 3840 jogadores por arena.",
"site.help.glossary.expandingLandTerms": "🌍 Termos do Expanding Land",
"site.help.glossary.dynamicMap": "<span class=\"emoji\">🗺️</span> Mapa dinâmico",
"site.help.glossary.expandingLandSMap": "O mapa do Expanding Land muda de tamanho automaticamente conforme o número de jogadores ativos. Mais jogadores = mapa maior. Menos jogadores = mapa menor. O mapa vai de ¼× a 4× do tamanho padrão, mantendo a densidade de jogadores constante, não importa quantas pessoas estejam online.",
"site.help.glossary.dangerZone": "<span class=\"emoji\">⚠️</span> Zona de perigo",
"site.help.glossary.whenTheExpandingLand": "Quando o mapa do Expanding Land está encolhendo, o anel externo vira a \"zona de perigo\". Jogadores com células nessa área recebem aumentos no multiplicador anti-team (+0.01 por ciclo de decaimento). A zona de perigo empurra os jogadores para o centro enquanto o mapa encolhe e impede que fiquem campando nas bordas.",
"site.help.glossary.sessionStats": "<span class=\"emoji\">📊</span> Estatísticas da sessão",
"site.help.glossary.afterDyingInExpanding": "Depois de morrer no Expanding Land, você vê as estatísticas da sua sessão: tempo vivo, maior massa alcançada, comida que você comeu e jogadores que você comeu. Essas estatísticas ajudam a acompanhar sua evolução com o tempo e comparar seu desempenho entre sessões.",
"site.help.glossary.coordinateScrambling": "<span class=\"emoji\">🔒</span> Embaralhamento de coordenadas",
"site.help.glossary.anAntiCheatFeature": "Um recurso anti-cheat do Expanding Land em que o servidor envia um deslocamento de coordenadas diferente para cada jogador. Isso impede que ferramentas de trapaça leiam as posições exatas de outros jogadores nos pacotes de rede: a visão de cada jogador é codificada de um jeito diferente.",
"site.help.glossary.wssTls": "<span class=\"emoji\">🔐</span> WSS / TLS",
"site.help.glossary.encryptedWebsocketConnectionsUsed": "Conexões WebSocket criptografadas usadas pelo Expanding Land. Todos os dados entre o seu navegador e o servidor do jogo são criptografados com TLS (a mesma tecnologia que protege o internet banking). Isso impede a interceptação de pacotes e ataques man-in-the-middle.",
"site.help.glossary.playExpandingLandFree": "🎮 Jogue Expanding Land de graça",
"site.help.glossary.bestIoGames2026": "Melhores jogos IO de 2026",
"site.help.glossary.elVsAgarIo": "EL vs Agar.io",
"site.help.glossary.playersAndBots": "Jogadores e bots"
}]);
if (window.LMi18n && window.LMi18n._drain) window.LMi18n._drain();
